        },
        {
          "case": "iff-forward",
          "status": "not_applicable",
          "reason": "The item refutes a universal assertion; step 1.1 proves nonexistence of irreducible subrepresentations directly, not one direction of an equivalence."
        },
        {
          "case": "iff-reverse",
          "status": "not_applicable",
          "reason": "No converse is available or claimed: the failure is proved for the regular representation of R, and the item does not assert that every noncompact group fails identically."
        }
      ],
      "finite_smoke": [],
      "risk_review": {
